def numeric_magnitude_proximity(prompts, completions, answer, **kwargs):
    import re
    import math

    def extract_number(s):
        s = s.strip()
        s = s.replace('\\frac', '').replace('\\cdot', '*')
        s = re.sub(r'\\left|\\right|\\,|\\;', '', s)

        # Handle simple fractions like \frac{a}{b}
        frac_match = re.search(r'\\frac\{([^}]+)\}\{([^}]+)\}', s)
        if frac_match:
            try:
                num = float(frac_match.group(1))
                den = float(frac_match.group(2))
                if den != 0:
                    return num / den
            except:
                pass

        # Handle simple decimals or integers
        num_match = re.search(r'-?\d+\.?\d*', s)
        if num_match:
            try:
                return float(num_match.group(0))
            except:
                pass
        return None

    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']
        m = re.search(r'<solution>(.*?)</solution>', response, re.DOTALL)
        if m is None:
            scores.append(-1.0)
            continue

        pred_str = m.group(1).strip()
        pred_val = extract_number(pred_str)
        true_val = extract_number(true_answer)

        if pred_val is None or true_val is None:
            # Fallback to exact match for non-numeric or complex expressions
            if is_correct(pred_str, true_answer):
                scores.append(5.0)
            else:
                scores.append(-1.0)
            continue

        if pred_val == true_val:
            scores.append(5.0)
        else:
            # Calculate relative error
            if true_val == 0:
                scores.append(-1.0 if pred_val != 0 else 5.0)
            else:
                rel_err = abs(pred_val - true_val) / abs(true_val)
                # Score decays with error
                score = 5.0 * (1.0 - min(rel_err, 1.0))
                if score < 0:
                    score = -1.0
                scores.append(score)
    return scores

